const cjk = (s: string) => (s.match(/[\u4e00-\u9fff]/g) || []).length;
const problems: string[] = [];
deck.slides.forEach((s: any, i: number) => {
  if (s.bullets) {
    if (s.bullets.length > 5) problems.push(`slide ${i} too many bullets`);
    s.bullets.forEach((b: string, j: number) => { if (cjk(b) > 42) problems.push(`slide ${i} bullet ${j} cjk=${cjk(b)}: ${b}`); });
  }
  if (s.cards && (s.cards.length < 3 || s.cards.length > 4)) problems.push(`slide ${i} cards=${s.cards.length}`);
  if (s.steps && (s.steps.length < 3 || s.steps.length > 4)) problems.push(`slide ${i} steps=${s.steps.length}`);
  if (s.headers && s.headers.length > 5) problems.push(`slide ${i} headers>5`);
  if (s.rows) {
    if (s.rows.length > 6) problems.push(`slide ${i} rows>6`);
    s.rows.forEach((r: string[]) => { if (r.length > 5) problems.push(`slide ${i} row cols>5`); });
  }
});
return { count: deck.slides.length, problems, layouts: deck.slides.map((s: any) => s.layout) };", "description": "Build deck and validate constraints"}

